import React, { useState, useEffect } from 'react';
import axios from 'axios';
import * as XLSX from 'xlsx';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

const userIcon = new L.Icon({
  iconUrl: 'https://cdn-icons-png.flaticon.com/512/854/854866.png',
  iconSize: [35, 35], iconAnchor: [17, 17], popupAnchor: [0, -15],
});

function RecenterMap({ points, userPos }) {
  const map = useMap();
  useEffect(() => {
    if (points && points.length > 1) {
      const bounds = L.latLngBounds(points);
      map.fitBounds(bounds, { padding: [50, 50] });
    } else if (userPos && !points.length) {
      map.setView(userPos, 15);
    }
  }, [points, userPos, map]);
  return null;
}

function App() {
  const [siroveAdrese, setSiroveAdrese] = useState([]);
  const [zadaci, setZadaci] = useState([]);
  const [putanja, setPutanja] = useState([]);
  const [loseAdrese, setLoseAdrese] = useState([]);
  const [mapInfo, setMapInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [statistika, setStatistika] = useState({ total_isporuka: 0, total_suma: 0 });
  const [zavrsnaAdresa, setZavrsnaAdresa] = useState("Centralna radna 4, Nova Pazova");
  const [userPos, setUserPos] = useState(null);

  const API_BASE = window.location.hostname === "localhost" ? "http://localhost:5001/api" : "/api";

  useEffect(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.watchPosition((p) => {
        setUserPos([p.coords.latitude, p.coords.longitude]);
      }, (e) => console.log("GPS Čeka..."), { enableHighAccuracy: true });
    }
    osveziStatistiku();
  }, []);

  const osveziStatistiku = async () => {
    try {
      const res = await axios.get(`${API_BASE}/statistika`);
      setStatistika(res.data);
    } catch (e) {}
  };

  const ucitajExcel = (e) => {
    const reader = new FileReader();
    reader.onload = (evt) => {
      const wb = XLSX.read(evt.target.result, { type: 'binary' });
      const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1 });
      const adrese = data.map(row => row[0]).filter(cell => cell && cell.toString().length > 3 && !cell.toString().toLowerCase().includes("redni"));
      setSiroveAdrese(adrese);
    };
    reader.readAsBinaryString(e.target.files[0]);
  };

  const optimizujRutu = async () => {
    setLoading(true);
    try {
      const res = await axios.post(`${API_BASE}/optimizuj`, { adrese: siroveAdrese, zavrsnaAdresa });
      setZadaci(res.data.sortirano);
      setPutanja(res.data.putanjaPoUlicama);
      setLoseAdrese(res.data.neuspesneAdrese);
      setMapInfo({ start: res.data.startCoords, end: res.data.krajCoords });
      setSiroveAdrese([]);
    } catch (err) { alert("Greška na serveru!"); }
    setLoading(false);
  };

  const uradjeno = zadaci.filter(z => z.isporuceno).length;

  return (
    <div style={{ padding: '10px', maxWidth: '800px', margin: 'auto', fontFamily: 'sans-serif', backgroundColor: '#f4f7f6', minHeight: '100vh' }}>
      <header style={{ textAlign: 'center', padding: '20px 0' }}>
        <h1 style={{ color: '#2c3e50', margin: 0, fontSize: '24px', fontWeight: '800' }}>SORTIRANJE ADRESA</h1>
        <div style={{ width: '45px', height: '4px', background: '#3498db', margin: '5px auto', borderRadius: '10px' }}></div>
      </header>

      <div style={{ background: '#2c3e50', color: 'white', padding: '15px', borderRadius: '15px', marginBottom: '15px', display: 'flex', justifyContent: 'space-around', fontSize: '13px' }}>
        <div style={{textAlign:'center'}}>MESEČNO<br/><b style={{color:'#3498db', fontSize:'18px'}}>{statistika.total_suma} RSD</b></div>
        <div style={{width:'1px', background:'#444'}}></div>
        <div style={{textAlign:'center'}}>PAKETA<br/><b style={{color:'#3498db', fontSize:'18px'}}>{statistika.total_isporuka}</b></div>
      </div>

      {!loading && siroveAdrese.length === 0 && zadaci.length === 0 && (
        <div style={{ border: '2px dashed #bdc3c7', padding: '40px', borderRadius: '200px', textAlign: 'center', backgroundColor: 'white' }}>
          <label style={{fontWeight:'bold'}}>Gde završavaš danas?</label>
          <input type="text" value={zavrsnaAdresa} onChange={(e)=>setZavrsnaAdresa(e.target.value)} style={{ width: '100%', padding: '12px', margin: '12px 0', borderRadius: '10px', border: '1px solid #ddd' }} />
          <input type="file" onChange={ucitajExcel} />
        </div>
      )}

      {siroveAdrese.length > 0 && (
        <div style={{ background: 'white', padding: '15px', borderRadius: '20px' }}>
          <h3>Ispravi adrese:</h3>
          {siroveAdrese.map((adr, index) => (
            <div key={index} style={{ display: 'flex', gap: '8px', marginBottom: '10px' }}>
              <input type="text" value={adr} onChange={(e) => { const n = [...siroveAdrese]; n[index] = e.target.value; setSiroveAdrese(n); }} style={{ flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #ddd' }} />
              <button onClick={() => setSiroveAdrese(siroveAdrese.filter((_, i) => i !== index))} style={{ background: '#ff7675', color: 'white', border: 'none', borderRadius: '8px', padding: '10px' }}>X</button>
            </div>
          ))}
          <button onClick={optimizujRutu} style={{ width: '100%', background: '#3498db', color: 'white', padding: '18px', borderRadius: '12px', fontWeight: 'bold' }}>POKRENI 🚀</button>
        </div>
      )}

      {loading && <h2 style={{textAlign: 'center', padding: '50px'}}>⏳ Obrađujem...</h2>}

      {(zadaci.length > 0 || userPos) && !loading && siroveAdrese.length === 0 && (
        <div>
          <div style={{ height: '380px', borderRadius: '20px', overflow: 'hidden', marginBottom: '15px', border: '3px solid white', boxShadow: '0 5px 15px rgba(0,0,0,0.1)' }}>
            <MapContainer center={userPos || [44.81, 20.46]} zoom={13} style={{ height: '100%' }}>
              <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
              {userPos && <Marker position={userPos} icon={userIcon}><Popup>Ti si ovde</Popup></Marker>}
              {zadaci.map((z, i) => !z.isporuceno && (
                <Marker key={i} position={z.coords} icon={L.divIcon({ html: `<div style="background:#3498db;color:white;border-radius:50%;width:26px;height:26px;display:flex;align-items:center;justify-content:center;border:2px solid white;font-weight:bold">${i+1}</div>`, className: '', iconSize: [26, 26] })}>
                  <Popup><b>{z.adresa}</b><br/><a href={`https://www.google.com/maps/search/?api=1&query=${z.coords[0]},${z.coords[1]}`} target="_blank" style={{display:'block', background:'#3498db', color:'white', padding:'8px', borderRadius:'5px', textAlign:'center', marginTop:'10px', textDecoration:'none'}}>NAVIGACIJA</a></Popup>
                </Marker>
              ))}
              {mapInfo && (
                <>
                  <Marker position={mapInfo.start} icon={new L.Icon({iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-green.png', iconSize: [20, 32]})} />
                  <Marker position={mapInfo.end} icon={new L.Icon({iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-red.png', iconSize: [20, 32]})} />
                  <Polyline positions={putanja} color="#3498db" weight={5} opacity={0.8} />
                </>
              )}
              <RecenterMap points={putanja} userPos={userPos} />
            </MapContainer>
          </div>

          {zadaci.length > 0 && (
            <>
              <div style={{ background: '#2ecc71', color: 'white', padding: '15px', borderRadius: '15px', textAlign: 'center', marginBottom: '15px' }}>
                <h2 style={{ margin: 0 }}>ZARADA DANAS: {uradjeno * 12} RSD</h2>
              </div>
              {zadaci.map((z, i) => (
                <div key={i} style={{ background: 'white', padding: '15px', borderRadius: '15px', marginBottom: '10px', opacity: z.isporuceno ? 0.4 : 1, display: 'flex', flexDirection: 'column', gap: '10px', boxShadow: '0 2px 5px rgba(0,0,0,0.02)', border: '1px solid #eee' }}>
                  <div style={{ fontWeight: '700', fontSize: '16px', color: '#2c3e50', textDecoration: z.isporuceno ? 'line-through' : 'none' }}>{i+1}. {z.adresa}</div>
                  <div style={{ display: 'flex', gap: '8px' }}>
                    {!z.isporuceno && <a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(z.adresa)}`} target="_blank" style={{ flex: 1, textAlign: 'center', background: '#3498db', color: 'white', textDecoration: 'none', padding: '12px', borderRadius: '10px', fontWeight: 'bold', fontSize: '13px' }}>MAPA 🗺️</a>}
                    <button onClick={() => {const n=[...zadaci]; n[i].isporuceno=!n[i].isporuceno; setZadaci(n);}} style={{ flex: 1, background: z.isporuceno ? '#dfe6e9' : '#2ecc71', color: z.isporuceno ? '#636e72' : 'white', border: 'none', borderRadius: '10px', fontWeight: 'bold', padding: '12px' }}>{z.isporuceno ? 'PONIŠTI' : 'ZAVRŠI ✅'}</button>
                  </div>
                </div>
              ))}
              <button onClick={async () => {
                 await axios.post(`${API_BASE}/sacuvaj-dan`, { broj_isporuka: uradjeno, ukupna_suma: uradjeno * 12 });
                 setZadaci([]); osveziStatistiku();
              }} style={{ width: '100%', padding: '18px', background: '#2c3e50', color: 'white', border: 'none', borderRadius: '15px', fontWeight: 'bold', marginTop: '15px' }}>💾 ZAVRŠI DAN I SAČUVAJ</button>
            </>
          )}
        </div>
      )}
      <footer style={{ textAlign: 'center', marginTop: '40px', paddingBottom: '20px', color: '#b2bec3', fontSize: '13px', fontStyle: 'italic' }}>By:Kurko Danijel</footer>
    </div>
  );
}

export default App;